import { memo } from 'react';
import type { BoardType } from '../model/types.ts';
import { RASTER } from '../model/types.ts';

export const EPOXY = '#c8a35e';
export const COPPER = '#b46f2e';

interface Props {
  idPrefix: string;
  width: number;
  height: number;
  type: BoardType;
  backgroundImage?: string;
  opacity: number;
  grid: boolean;
  /** solder side: copper pads around the holes */
  solderSide: boolean;
}

/** Board substrate, as generated by BoardGen in BlackBoard 1.x, plus grid. */
export const BoardBackground = memo(function BoardBackground({ idPrefix, width, height, type, backgroundImage, opacity, grid, solderSide }: Props) {
  const lastX = Math.floor((width - 1) / RASTER) * RASTER;
  const lastY = Math.floor((height - 1) / RASTER) * RASTER;
  const perf = type === 'HOLES' || type === 'STRIPES';
  const paper = !perf;
  const id = (s: string) => `${idPrefix}-${s}`;
  return (
    <g opacity={opacity}>
      <defs>
        <pattern id={id('holes')} width={RASTER} height={RASTER} patternUnits="userSpaceOnUse" x={RASTER / 2} y={RASTER / 2}>
          {solderSide && type === 'HOLES' && <circle cx={8} cy={8} r={6} fill={COPPER} />}
          <circle cx={8} cy={8} r={4} fill="#1a1a1a" />
          <circle cx={8} cy={8} r={3} fill="#c4c4c4" />
          <circle cx={7.3} cy={7.3} r={1.2} fill="#e8e8e8" />
        </pattern>
        <pattern id={id('stripes')} width={RASTER} height={RASTER} patternUnits="userSpaceOnUse" x={0} y={RASTER / 2}>
          <rect x={0} y={3} width={RASTER} height={RASTER - 5} fill={COPPER} />
          <rect x={0} y={3} width={RASTER} height={1.5} fill="#d08a48" />
        </pattern>
        <pattern id={id('grid')} width={RASTER} height={RASTER} patternUnits="userSpaceOnUse">
          <path d={`M ${RASTER} 0 L 0 0 0 ${RASTER}`} fill="none" stroke="#e5e7eb" strokeWidth={0.6} />
        </pattern>
        <pattern id={id('grid10')} width={RASTER * 10} height={RASTER * 10} patternUnits="userSpaceOnUse">
          <path d={`M ${RASTER * 10} 0 L 0 0 0 ${RASTER * 10}`} fill="none" stroke="#d1d5db" strokeWidth={0.9} />
        </pattern>
      </defs>
      <rect x={0} y={0} width={width} height={height} fill={perf ? EPOXY : '#ffffff'} />
      {backgroundImage && <image href={backgroundImage} x={0} y={0} width={width} height={height} preserveAspectRatio="xMinYMin meet" />}
      {type === 'STRIPES' && <rect x={0} y={RASTER / 2} width={width} height={Math.max(0, lastY - RASTER / 2 + RASTER / 2)} fill={`url(#${id('stripes')})`} />}
      {perf && lastX >= RASTER && lastY >= RASTER && (
        <rect x={RASTER / 2} y={RASTER / 2} width={lastX} height={lastY} fill={`url(#${id('holes')})`} />
      )}
      {paper && grid && (
        <>
          <rect x={0} y={0} width={width} height={height} fill={`url(#${id('grid')})`} />
          <rect x={0} y={0} width={width} height={height} fill={`url(#${id('grid10')})`} />
        </>
      )}
      {perf && <Rulers width={width} height={height} />}
    </g>
  );
});

function Rulers({ width, height }: { width: number; height: number }) {
  const cols: number[] = [];
  const rows: number[] = [];
  for (let x = RASTER; x < width - RASTER / 2; x += RASTER) cols.push(x);
  for (let y = RASTER; y < height - RASTER / 2; y += RASTER) rows.push(y);
  return (
    <g fontSize={5.5} fontFamily="Inter, Arial, sans-serif" fill="#3b2a12" textAnchor="middle" style={{ pointerEvents: 'none' }}>
      {cols.map((x, i) => (
        <text key={'c' + x} x={x} y={6}>
          {i + 1}
        </text>
      ))}
      {rows.map((y, i) => (
        <text key={'r' + y} x={4} y={y + 2}>
          {i + 1}
        </text>
      ))}
    </g>
  );
}
